[{"order":1,"type":"heading","text":"Pinia State Management in Vue.js: Stores, Actions, and Getters"},{"order":2,"type":"paragraph","text":"Pinia is the official, modular state management library for Vue.js. It replaces Vuex by offering a simpler, lightweight, and fully type-safe API. Pinia stores consist of three core concepts: State (the data source), Getters (computed values based on state), and Actions (methods to mutate state or handle async workflows)."},{"order":3,"type":"subheading","text":"Defining a Pinia Store"},{"order":4,"type":"paragraph","text":"Stores are defined using the 'defineStore()' function. Pinia supports two syntax options: Option Stores (structured like Vue's Options API) and Setup Stores (structured like Vue's Composition API). Setup Stores are recommended for modern Vue 3 applications due to their flexibility."},{"order":5,"type":"code","text":"import { defineStore } from 'pinia';
import { ref, computed } from 'vue';

// Setup Store syntax
export const useCounterStore = defineStore('counter', () => {
  // State
  const count = ref(0);

  // Getters
  const doubleCount = computed(() => count.value * 2);

  // Actions
  function increment() {
    count.value++;
  }

  return { count, doubleCount, increment };
});"},{"order":6,"type":"subheading","text":"Working with Getters"},{"order":7,"type":"paragraph","text":"Getters are exact equivalents to 'computed' properties in components. They allow you to derive computed state efficiently and automatically cache the result until state dependencies change. Getters can also return dynamic functions to accept custom arguments."},{"order":8,"type":"code","text":"import { defineStore } from 'pinia';

// Option Store syntax showing getters
export const useUserStore = defineStore('user', {
  state: () => ({
    users: [
      { id: 1, name: 'Alice', active: true },
      { id: 2, name: 'Bob', active: false }
    ]
  }),
  getters: {
    // Standard getter using state parameter
    activeUsers: (state) => state.users.filter(user => user.active),

    // Parameterized getter returning a function
    getUserById: (state) => {
      return (userId) => state.users.find(user => user.id === userId);
    }
  }
});"},{"order":9,"type":"subheading","text":"Executing Business Logic with Actions"},{"order":10,"type":"paragraph","text":"Unlike Vuex, Pinia eliminates mutations entirely. Actions are standard synchronous or asynchronous methods used to fetch data, perform computations, and update store state directly."},{"order":11,"type":"code","text":"import { defineStore } from 'pinia';

export const useProductStore = defineStore('products', {
  state: () => ({
    items: [],
    loading: false,
    error: null
  }),
  actions: {
    async fetchProducts() {
      this.loading = true;
      this.error = null;
      try {
        const response = await fetch('https://api.example.com/products');
        this.items = await response.json();
      } catch (err) {
        this.error = 'Failed to fetch products';
      } finally {
        this.loading = false;
      }
    }
  }
});"},{"order":12,"type":"subheading","text":"Consuming Stores in Vue Components"},{"order":13,"type":"paragraph","text":"To extract reactive state properties and getters without breaking Vue reactivity, always use 'storeToRefs()'. Direct actions can be destructured straight from the store instance."},{"order":14,"type":"code","text":"<script setup>
import { storeToRefs } from 'pinia';
import { useCounterStore } from './stores/counter';

const counterStore = useCounterStore();

// storeToRefs preserves reactivity for properties and getters
const { count, doubleCount } = storeToRefs(counterStore);

// Actions can be extracted directly as normal methods
const { increment } = counterStore;
</script>

<template>
  <div>
    <p>Count: {{ count }}</p>
    <p>Double: {{ doubleCount }}</p>
    <button @click="increment">Increment</button>
  </div>
</template>"},{"order":15,"type":"subheading","text":"Pinia Best Practices"},{"order":16,"type":"bullet_point","text":"Always wrap state destructuring with 'storeToRefs()' to prevent loss of Vue reactivity."},{"order":17,"type":"bullet_point","text":"Keep getters pure by avoiding direct mutations or side effects inside getter functions."},{"order":18,"type":"bullet_point","text":"Encapsulate API requests and complex business logic inside actions rather than writing fetch code in component files."},{"order":19,"type":"bullet_point","text":"Organize your architecture by creating separate store files per domain module (e.g., 'useAuthStore.js', 'useCartStore.js')."}]
